var scene=UnityEditor.SceneManagement.EditorSceneManager.GetActiveScene();var b=UnityEngine.GameObject.Find("BuildingTilemap");var br=b.GetComponent<UnityEngine.Tilemaps.TilemapRenderer>();var bv=UnityEngine.GameObject.Find("BuildingVisuals");var sc=UnityEngine.GameObject.Find("StreetClutter");var col=UnityEngine.GameObject.Find("CollisionTilemap");var tc=col.GetComponent<UnityEngine.Tilemaps.TilemapCollider2D>();var cc=col.GetComponent<UnityEngine.CompositeCollider2D>();var maps=UnityEngine.Object.FindObjectsByType<UnityEngine.Tilemaps.Tilemap>(UnityEngine.FindObjectsSortMode.None);var counts=new System.Collections.Generic.List<object>();foreach(var m in maps){if(!m.gameObject.scene.IsValid())continue;int n=0;foreach(var p in m.cellBounds.allPositionsWithin)if(m.GetTile(p)!=null)n++;counts.Add(new{name=m.name,cells=n});}return new{scene=scene.path,buildingRendererEnabled=br.enabled,buildingVisuals=bv.transform.childCount,streetClutter=sc.transform.childCount,collisionTilemapCollider=tc.enabled,collisionComposite=cc.enabled,maps=counts};
